import{_ as n,l as r,o as e,c as l,v as t,p as s,x as i,d,i as _,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"合成控制","description":"","frontmatter":{"title":"合成控制","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/synthetic-control.md","filePath":"econ/synthetic-control.md","lastUpdated":1789023840000}'),E={name:"econ/synthetic-control.md"};function c(A,a,h,m,u,D){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="合成控制" tabindex="-1">合成控制 <a class="header-anchor" href="#合成控制" aria-label="Permalink to &quot;合成控制&quot;">​</a></h1><div class="epigraph"><p>只有一个（或几个）处理单位时，不要任意挑一个邻居当对照；用处理前轨迹把对照库权合成一个「合成的自己」。</p><footer>—— Abadie and Gardeazabal, The Economic Costs of Conflict: A Case Study of the Basque Country, AER 2003；Abadie, Diamond and Hainmueller, JASA 2010</footer></div><p><a href="/econ/rdd">上一课</a>靠门槛两侧的局部随机。本课缺口是：加州烟税、巴斯克冲突、德国统一这类<strong>一个处理、没有门槛</strong>的案例。匹配下一课把同一思想推广到许多处理单位。本课钉 Abadie 的合成控制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>处理区 \\(i=1\\) 在 \\(T_0\\) 后受干预，候选对照 \\(j=2,\\ldots,J\\) 不受。单差用某一个 \\(j\\) 任意。DiD 用所有 \\(j\\) 的简单平均，但处理区可能在水平上就与平均不同。合成控制选权重 \\(w_j\\ge 0\\)，\\(\\sum w_j=1\\)，使处理前</p> \\[\\sum_{t\\le T_0} \\Bigl(Y_{1t}-\\sum_j w_j Y_{jt}\\Bigr)^2 \\]<p>（可加协变量）尽量小。处理后 \\(\\hat Y_{1t}(0)=\\sum_j w_j Y_{jt}\\)，效应是 \\(Y_{1t}-\\hat Y_{1t}(0)\\)。缺口是：权重是设计，不是又一次 TWFE；推断不能靠常规聚类 \\(t\\)。</p><p><span class="marginnote">Abadie–Diamond–Hainmueller 对加州 1988 年烟税：合成加州由若干州的凸组合构成，处理前吸烟路径贴合，处理后分叉。安慰剂把假处理派给每个对照州，看加州的缺口是否极端。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约束为凸组合，禁止外推到对照库凸包之外——这是与回归对照的关键差别：OLS 可以给负权重、系数和不必为 1。拟合过好（处理前期太短、预测变量太多）会过拟合噪声，处理后缺口不可信。推断：排列检验（安慰剂时点或安慰剂单位）；近年有共形推断、渐近理论（Abadie 后续工作），本课以安慰剂为最小装置。</p>',10)),(e(),s(p,null,{default:i(()=>[_(o,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E5%AF%B9%E7%85%A7%E5%BA%93%22%5D%20--%3E%20W%5B%22%E5%87%B8%E6%9D%83%E9%87%8D%20w%22%5D%0A%20%20PRE%5B%22%E5%A4%84%E7%90%86%E5%89%8D%E6%8B%9F%E5%90%88%22%5D%20--%3E%20W%0A%20%20W%20--%3E%20SC%5B%22%E5%90%88%E6%88%90%20Y(0)%22%5D%0A%20%20SC%20--%3E%20GAP%5B%22%E5%A4%84%E7%90%86%E5%90%8E%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20PLAC%5B%22%E5%AE%89%E6%85%B0%E5%89%82%E6%8E%92%E5%88%97%22%5D%20--%3E%20INF%5B%22%E7%BC%BA%E5%8F%A3%E6%98%AF%E5%90%A6%E6%9E%81%E7%AB%AF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>若处理前拟合已经差，不要报告处理后缺口——设计失败，不是「效应为零」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是用对照库张成处理单位的反事实路径。平行趋势是「对照组平均与处理组同走」；合成控制是「加权后同走」，权重由处理前数据选。这仍是对 \\(Y(0)\\) 可预测性的假设：没有同时冲击只打中处理单位。SUTVA：对照州不能被溢出污染（邻州走私香烟）。</p><p>与 DiD：合成控制可以看成数据驱动的对照组；DiD 是 \\(w_j=1/(J-1)\\)。交错多处理单位时，合成控制要逐个做或改用面板方法，不要把 TWFE 负权重问题假装已经消失。</p><p><span class="marginnote">外推禁令：若处理单位在处理前就在所有对照的凸包之外，不存在合格合成。应报告，而不是改用负权重回归硬造。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把巴斯克或加州的点估计外推成冲突与税收的普遍弹性。一个处理单位的外部有效天然薄。下一课匹配与倾向得分：许多处理、许多对照，回到截面或面板的条件独立，而不是一条合成路径。量化栏的事件研究对照的是证券，不是州，不混写。</p><p>后课默认：单（少）处理单位优先考虑凸合成加安慰剂；处理前拟合差则停止。匹配下一课处理「多个 \\(i\\) 被处理」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合成控制 = 对照库上的凸组合，贴处理前路径。</li><li>禁止负权重外推；拟合差则设计失败。</li><li>推断以安慰剂排列为最小标准。</li><li>与 DiD：把简单平均换成数据驱动权重。</li><li>出处：Abadie and Gardeazabal, <em>AER</em> 2003；Abadie, Diamond and Hainmueller, <em>JASA</em> 2010。</li></ul>',10))])}const b=n(E,[["render",c]]);export{B as __pageData,b as default};
